def get_daily_news(limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0197000" if __import__("os").path.isdir("./environment_mix/0197000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    endpoint = "get-daily-news"

    def _dt_parse(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _dt_iso(dt):
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    # observable dynamics: log every call + enforce basic rate/quota if a log collection exists
    def _find_log_file():
        for cand in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json", "api_requests.json"):
            p = os.path.join(_DB, cand)
            if os.path.exists(p):
                return cand
        # if none exists, prefer not to create new ones (unknown vendor file); still proceed without enforcement
        return None

    log_file = _find_log_file()

    def _read_logs():
        if not log_file:
            return []
        rows = _load(log_file)
        return rows if isinstance(rows, list) else []

    def _write_logs(rows):
        if log_file:
            _save(log_file, rows)

    def _extract_ts(r):
        if not isinstance(r, dict):
            return None
        return _dt_parse(r.get("timestamp") or r.get("created_at") or r.get("time"))

    def _log_and_maybe_limit(final_status, error=None, meta=None):
        rows = _read_logs()
        # Basic vendor-like limits (only enforced if logs exist)
        if log_file:
            one_min_ago = now - datetime.timedelta(seconds=60)
            one_day_ago = now - datetime.timedelta(days=1)
            recent_min = 0
            recent_day = 0
            for r in rows:
                ts = _extract_ts(r)
                if not ts:
                    continue
                if ts >= one_min_ago:
                    recent_min += 1
                if ts >= one_day_ago:
                    recent_day += 1
            # conservative defaults
            if recent_min >= 120:
                # still log the refused request
                latency_ms = int((time.time() - t0) * 1000)
                rows.append({
                    "id": "req_" + hashlib.sha256(f"{endpoint}:{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
                    "endpoint": endpoint,
                    "status": "error",
                    "error_code": "RATE_LIMIT",
                    "error_message": "Rate limit exceeded.",
                    "timestamp": _dt_iso(now),
                    "latency_ms": latency_ms,
                    "meta": meta or {}
                })
                _write_logs(rows)
                return _err("RATE_LIMIT", "Rate limit exceeded.")
            if recent_day >= 5000:
                latency_ms = int((time.time() - t0) * 1000)
                rows.append({
                    "id": "req_" + hashlib.sha256(f"{endpoint}:{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
                    "endpoint": endpoint,
                    "status": "error",
                    "error_code": "QUOTA_EXCEEDED",
                    "error_message": "Daily quota exceeded.",
                    "timestamp": _dt_iso(now),
                    "latency_ms": latency_ms,
                    "meta": meta or {}
                })
                _write_logs(rows)
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        # log success/error
        latency_ms = int((time.time() - t0) * 1000)
        if log_file:
            row = {
                "id": "req_" + hashlib.sha256(f"{endpoint}:{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
                "endpoint": endpoint,
                "status": final_status,
                "timestamp": _dt_iso(now),
                "latency_ms": latency_ms,
                "meta": meta or {}
            }
            if error:
                row["error_code"] = error.get("code")
                row["error_message"] = error.get("message")
            rows.append(row)
            _write_logs(rows)
        return None

    # validate limit
    if limit is None:
        limit_n = 20
    else:
        if not isinstance(limit, int) or isinstance(limit, bool) or limit <= 0:
            e = _err("VALIDATION_ERROR", "limit must be a positive integer", field="limit")
            maybe = _log_and_maybe_limit("error", error=e["error"], meta={"limit": limit, "cursor": cursor})
            return maybe if maybe else e
        limit_n = limit

    # cursor: vendor allows passing arbitrary strings; only error on malformed/expired cursors we minted
    cursor_payload = None
    if cursor is not None:
        if not isinstance(cursor, str):
            e = _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")
            maybe = _log_and_maybe_limit("error", error=e["error"], meta={"limit": limit, "cursor": cursor})
            return maybe if maybe else e
        c = cursor.strip()
        if c == "":
            e = _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
            maybe = _log_and_maybe_limit("error", error=e["error"], meta={"limit": limit, "cursor": cursor})
            return maybe if maybe else e
        # accept unknown cursors as "start from beginning" unless it matches our cursor format but is invalid/expired
        if c.startswith("cur_vrg_"):
            try:
                raw = base64.urlsafe_b64decode(c[len("cur_vrg_"):].encode("utf-8") + b"===").decode("utf-8")
                cursor_payload = json.loads(raw)
            except Exception:
                e = _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
                maybe = _log_and_maybe_limit("error", error=e["error"], meta={"limit": limit, "cursor": cursor})
                return maybe if maybe else e
            if not isinstance(cursor_payload, dict) or cursor_payload.get("v") != 1 or cursor_payload.get("t") != "daily":
                e = _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
                maybe = _log_and_maybe_limit("error", error=e["error"], meta={"limit": limit, "cursor": cursor})
                return maybe if maybe else e
            exp = _dt_parse(cursor_payload.get("exp"))
            if not exp:
                e = _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
                maybe = _log_and_maybe_limit("error", error=e["error"], meta={"limit": limit, "cursor": cursor})
                return maybe if maybe else e
            if now > exp:
                e = _err("VALIDATION_ERROR", "cursor is expired", field="cursor")
                maybe = _log_and_maybe_limit("error", error=e["error"], meta={"limit": limit, "cursor": cursor})
                return maybe if maybe else e

    articles = _load("articles.json")
    if not isinstance(articles, list):
        articles = []

    start = now - datetime.timedelta(days=1)

    eligible = []
    for a in articles:
        if not isinstance(a, dict):
            continue
        if a.get("status") != "active":
            continue
        if a.get("indexed_at") in (None, ""):
            continue
        pub = _dt_parse(a.get("published_at"))
        if not pub:
            continue
        if pub < start:
            continue
        eligible.append((pub, a))

    eligible.sort(key=lambda x: x[0], reverse=True)

    offset = 0
    if cursor_payload:
        # offset-based cursor for stable pagination
        off = cursor_payload.get("o")
        if not isinstance(off, int) or off < 0:
            e = _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
            maybe = _log_and_maybe_limit("error", error=e["error"], meta={"limit": limit, "cursor": cursor})
            return maybe if maybe else e
        # if offset is beyond list, treat as NOT_FOUND (cursor doesn't correspond to a known page)
        if off > len(eligible):
            e = _err("NOT_FOUND", "cursor does not correspond to a known page", cursor=cursor)
            maybe = _log_and_maybe_limit("error", error=e["error"], meta={"limit": limit, "cursor": cursor})
            return maybe if maybe else e
        offset = off

    page_items = [a for _, a in eligible[offset:offset + limit_n]]
    next_offset = offset + len(page_items)
    has_more = next_offset < len(eligible)

    next_cursor = None
    if has_more:
        payload = {
            "v": 1,
            "t": "daily",
            "o": next_offset,
            "exp": _dt_iso(now + datetime.timedelta(hours=6))
        }
        enc = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")).decode("utf-8").rstrip("=")
        next_cursor = "cur_vrg_" + enc

    maybe = _log_and_maybe_limit("success", meta={"limit": limit_n, "cursor": cursor, "returned": len(page_items)})
    if maybe:
        return maybe

    return {
        "data": page_items,
        "meta": {
            "total": len(eligible),
            "limit": limit_n,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

