def search_news(keyword, days=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0197000" if __import__("os").path.isdir("./environment_mix/0197000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    endpoint = "search-news"
    requests_file = "request_logs.json"

    def _dt_parse(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _dt_iso(dt):
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _log(status, code=None, message=None, meta=None):
        logs = _load(requests_file)
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{now.timestamp()}|{len(logs)}".encode("utf-8")).hexdigest()[:16],
            "endpoint": endpoint,
            "status": status,
            "error_code": code,
            "error_message": message,
            "meta": meta or {},
            "latency_ms": latency_ms,
            "created_at": _dt_iso(now),
        }
        logs.append(row)
        _save(requests_file, logs)

    def _enforce_limits():
        logs = _load(requests_file)
        if not isinstance(logs, list):
            return None
        window_s = 60
        max_in_window = 30  # stricter for search
        cutoff = now - datetime.timedelta(seconds=window_s)
        cnt = 0
        for r in reversed(logs[-2000:]):
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            ts = _dt_parse(r.get("created_at"))
            if ts and ts >= cutoff:
                cnt += 1
        if cnt >= max_in_window:
            return _err("RATE_LIMIT", f"Rate limit exceeded for {endpoint}. Try again later.", limit=max_in_window, window_seconds=window_s)
        day_cutoff = now - datetime.timedelta(days=1)
        day_cnt = 0
        for r in reversed(logs[-20000:]):
            if not isinstance(r, dict):
                continue
            ts = _dt_parse(r.get("created_at"))
            if ts and ts >= day_cutoff:
                day_cnt += 1
        if day_cnt >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded. Try again later.", quota=5000, window_days=1)
        return None

    # Enforce limits early
    limerr = _enforce_limits()
    if limerr:
        _log("error", limerr["error"]["code"], limerr["error"]["message"])
        return limerr

    # Validate keyword
    if not isinstance(keyword, str):
        # Store rejected request
        sr = _load("search_requests.json")
        if not isinstance(sr, list):
            sr = []
        rid = "sr_" + hashlib.sha256(f"{now.timestamp()}|{len(sr)}|kw_type".encode("utf-8")).hexdigest()[:16]
        row = {
            "id": rid,
            "keyword": "" if keyword is None else str(keyword),
            "days": 30 if days is None else days,
            "requested_start_at": _dt_iso(now - datetime.timedelta(days=30)),
            "requested_end_at": _dt_iso(now),
            "status": "rejected",
            "result_count": None,
            "rejection_reason": "empty_keyword",
            "created_at": _dt_iso(now),
            "updated_at": _dt_iso(now),
        }
        sr.append(row)
        _save("search_requests.json", sr)
        _log("error", "VALIDATION_ERROR", "keyword must be a non-empty string")
        return _err("VALIDATION_ERROR", "keyword must be a non-empty string")

    kw = keyword.strip()
    if len(kw) == 0:
        sr = _load("search_requests.json")
        if not isinstance(sr, list):
            sr = []
        rid = "sr_" + hashlib.sha256(f"{now.timestamp()}|{len(sr)}|empty".encode("utf-8")).hexdigest()[:16]
        row = {
            "id": rid,
            "keyword": keyword,
            "days": 30 if days is None else days,
            "requested_start_at": _dt_iso(now - datetime.timedelta(days=30)),
            "requested_end_at": _dt_iso(now),
            "status": "rejected",
            "result_count": None,
            "rejection_reason": "empty_keyword",
            "created_at": _dt_iso(now),
            "updated_at": _dt_iso(now),
        }
        sr.append(row)
        _save("search_requests.json", sr)
        _log("error", "VALIDATION_ERROR", "keyword must be non-empty after trimming")
        return _err("VALIDATION_ERROR", "keyword must be non-empty after trimming")

    if len(kw) > 200:
        sr = _load("search_requests.json")
        if not isinstance(sr, list):
            sr = []
        rid = "sr_" + hashlib.sha256(f"{now.timestamp()}|{len(sr)}|kwlen".encode("utf-8")).hexdigest()[:16]
        row = {
            "id": rid,
            "keyword": kw[:200],
            "days": 30 if days is None else days,
            "requested_start_at": _dt_iso(now - datetime.timedelta(days=30)),
            "requested_end_at": _dt_iso(now),
            "status": "rejected",
            "result_count": None,
            "rejection_reason": "empty_keyword",
            "created_at": _dt_iso(now),
            "updated_at": _dt_iso(now),
        }
        sr.append(row)
        _save("search_requests.json", sr)
        _log("error", "VALIDATION_ERROR", "keyword length must be between 1 and 200")
        return _err("VALIDATION_ERROR", "keyword length must be between 1 and 200")

    # Validate days (default 30). Must be numeric between 1 and 365 inclusive.
    d = 30 if days is None else days
    # JSON schema says number, but accept int/float; reject bool.
    if isinstance(d, bool) or not isinstance(d, (int, float)):
        sr = _load("search_requests.json")
        if not isinstance(sr, list):
            sr = []
        rid = "sr_" + hashlib.sha256(f"{now.timestamp()}|{len(sr)}|daystype".encode("utf-8")).hexdigest()[:16]
        row = {
            "id": rid,
            "keyword": kw,
            "days": d,
            "requested_start_at": _dt_iso(now - datetime.timedelta(days=30)),
            "requested_end_at": _dt_iso(now),
            "status": "rejected",
            "result_count": None,
            "rejection_reason": "invalid_days",
            "created_at": _dt_iso(now),
            "updated_at": _dt_iso(now),
        }
        sr.append(row)
        _save("search_requests.json", sr)
        _log("error", "VALIDATION_ERROR", "days must be a number between 1 and 365")
        return _err("VALIDATION_ERROR", "days must be a number between 1 and 365")

    # days must be integer-ish for storage/logic; vendor schema says number but constraint is integer range.
    if d < 1 or d > 365:
        sr = _load("search_requests.json")
        if not isinstance(sr, list):
            sr = []
        rid = "sr_" + hashlib.sha256(f"{now.timestamp()}|{len(sr)}|daysrange".encode("utf-8")).hexdigest()[:16]
        row = {
            "id": rid,
            "keyword": kw,
            "days": d,
            "requested_start_at": _dt_iso(now - datetime.timedelta(days=30)),
            "requested_end_at": _dt_iso(now),
            "status": "rejected",
            "result_count": None,
            "rejection_reason": "invalid_days",
            "created_at": _dt_iso(now),
            "updated_at": _dt_iso(now),
        }
        sr.append(row)
        _save("search_requests.json", sr)
        _log("error", "VALIDATION_ERROR", "days must be between 1 and 365")
        return _err("VALIDATION_ERROR", "days must be between 1 and 365")

    requested_end = now
    requested_start = now - datetime.timedelta(days=float(d))
    kw_low = kw.lower()

    # Create search request row as received, then fulfill/reject as needed (here: fulfill)
    sr = _load("search_requests.json")
    if not isinstance(sr, list):
        sr = []
    rid = "sr_" + hashlib.sha256(f"{now.timestamp()}|{len(sr)}|{kw_low}".encode("utf-8")).hexdigest()[:16]
    req_row = {
        "id": rid,
        "keyword": kw,
        "days": float(d),
        "requested_start_at": _dt_iso(requested_start),
        "requested_end_at": _dt_iso(requested_end),
        "status": "received",
        "result_count": None,
        "rejection_reason": None,
        "created_at": _dt_iso(now),
        "updated_at": _dt_iso(now),
    }
    sr.append(req_row)
    _save("search_requests.json", sr)

    # Search articles
    articles = _load("articles.json")
    if not isinstance(articles, list):
        articles = []

    matches = []
    for a in articles:
        if not isinstance(a, dict):
            continue
        if a.get("status") != "active":
            continue
        if a.get("indexed_at") in (None, ""):
            continue
        pub = _dt_parse(a.get("published_at"))
        if not pub:
            continue
        if pub < requested_start or pub > requested_end:
            continue
        title = a.get("title") or ""
        summary = a.get("summary") or ""
        content = a.get("content_text") or ""
        hay = f"{title}\n{summary}\n{content}".lower()
        if kw_low in hay:
            matches.append(a)

    matches.sort(key=lambda x: (_dt_parse(x.get("published_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)

    # Fulfill request: transition received -> fulfilled, set result_count
    sr2 = _load("search_requests.json")
    if not isinstance(sr2, list):
        sr2 = sr
    updated = False
    for r in sr2:
        if isinstance(r, dict) and r.get("id") == rid:
            r["status"] = "fulfilled"
            r["result_count"] = int(len(matches))
            r["updated_at"] = _dt_iso(now)
            updated = True
            break
    if updated:
        _save("search_requests.json", sr2)

    _log("ok", meta={"keyword": kw, "days": float(d), "returned": len(matches)})
    return {
        "data": matches,
        "meta": {
            "keyword": kw,
            "days": float(d),
            "requested_start_at": _dt_iso(requested_start),
            "requested_end_at": _dt_iso(requested_end),
            "total": len(matches),
            "search_request_id": rid
        }
    }

def list_sources(status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0197000" if __import__("os").path.isdir("./environment_mix/0197000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    endpoint = "list-sources"

    def _dt_parse(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _dt_iso(dt):
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _find_log_file():
        for cand in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json", "api_requests.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                return cand
        return None

    log_file = _find_log_file()

    def _read_logs():
        if not log_file:
            return []
        rows = _load(log_file)
        return rows if isinstance(rows, list) else []

    def _write_logs(rows):
        if log_file:
            _save(log_file, rows)

    def _enforce_limits_and_log(final_status, error_code=None, error_message=None, meta=None, cursor_used=None):
        rows = _read_logs()
        if log_file:
            one_min_ago = now - datetime.timedelta(seconds=60)
            one_day_ago = now - datetime.timedelta(days=1)

            recent_min = 0
            recent_day = 0
            for r in rows:
                ts = _dt_parse((r or {}).get("timestamp") or (r or {}).get("created_at")) if isinstance(r, dict) else None
                if not ts:
                    continue
                if ts >= one_min_ago:
                    recent_min += 1
                if ts >= one_day_ago:
                    recent_day += 1

            if recent_min >= 120:
                latency_ms = int((time.time() - t0) * 1000)
                rows.append({
                    "id": f"req_{len(rows)+1}",
                    "endpoint": endpoint,
                    "status": "RATE_LIMIT",
                    "error_code": "RATE_LIMIT",
                    "error_message": "Rate limit exceeded (120 requests/min).",
                    "latency_ms": latency_ms,
                    "timestamp": _dt_iso(now),
                    "meta": {"cursor": cursor_used, **(meta or {})},
                })
                _write_logs(rows)
                return _err("RATE_LIMIT", "Rate limit exceeded (120 requests/min).")
            if recent_day >= 10000:
                latency_ms = int((time.time() - t0) * 1000)
                rows.append({
                    "id": f"req_{len(rows)+1}",
                    "endpoint": endpoint,
                    "status": "QUOTA_EXCEEDED",
                    "error_code": "QUOTA_EXCEEDED",
                    "error_message": "Daily quota exceeded (10000 requests/day).",
                    "latency_ms": latency_ms,
                    "timestamp": _dt_iso(now),
                    "meta": {"cursor": cursor_used, **(meta or {})},
                })
                _write_logs(rows)
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded (10000 requests/day).")

        if log_file:
            latency_ms = int((time.time() - t0) * 1000)
            rows.append({
                "id": f"req_{len(rows)+1}",
                "endpoint": endpoint,
                "status": final_status,
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": latency_ms,
                "timestamp": _dt_iso(now),
                "meta": {"cursor": cursor_used, **(meta or {})},
            })
            _write_logs(rows)
        return None

    # Validate params
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "disabled"):
            e = _err("VALIDATION_ERROR", "status must be one of: active, disabled", field="status")
            _enforce_limits_and_log("error", e["error"]["code"], e["error"]["message"], meta={"field": "status"}, cursor_used=cursor)
            return e
    if limit is None:
        limit = 20
    if not isinstance(limit, int) or isinstance(limit, bool) or limit <= 0:
        e = _err("VALIDATION_ERROR", "limit must be a positive integer", field="limit")
        _enforce_limits_and_log("error", e["error"]["code"], e["error"]["message"], meta={"field": "limit"}, cursor_used=cursor)
        return e
    if cursor is not None and not isinstance(cursor, str):
        e = _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")
        _enforce_limits_and_log("error", e["error"]["code"], e["error"]["message"], meta={"field": "cursor"}, cursor_used=cursor)
        return e

    limit_err = _enforce_limits_and_log("pending", meta={"phase": "precheck"}, cursor_used=cursor)
    if isinstance(limit_err, dict) and "error" in limit_err:
        return limit_err

    sources = _load("sources.json")
    if not isinstance(sources, list):
        sources = []

    filtered = []
    for s in sources:
        if not isinstance(s, dict):
            continue
        if status is not None and s.get("status") != status:
            continue
        filtered.append(s)

    filtered.sort(key=lambda r: (_dt_parse(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)

    # Cursor behavior: accept encoded cursor or raw id; do not reject as "malformed" for plain ids
    start = 0
    if cursor:
        decoded = None
        if cursor.startswith("cur_"):
            token = cursor[4:]
            try:
                decoded = base64.urlsafe_b64decode(token.encode("utf-8")).decode("utf-8")
            except Exception:
                decoded = None
        after_id = decoded[3:] if decoded and decoded.startswith("id:") else cursor

        idx = None
        for i, s in enumerate(filtered):
            if s.get("id") == after_id:
                idx = i
                break
        if idx is None:
            e = _err("NOT_FOUND", "cursor does not correspond to a known page", cursor=cursor)
            _enforce_limits_and_log("error", e["error"]["code"], e["error"]["message"], meta={"cursor": cursor}, cursor_used=cursor)
            return e
        start = idx + 1

    page = filtered[start:start + limit]
    next_cursor = None
    if start + limit < len(filtered) and page:
        last_id = page[-1].get("id")
        if isinstance(last_id, str) and last_id:
            token = base64.urlsafe_b64encode(f"id:{last_id}".encode("utf-8")).decode("utf-8")
            next_cursor = "cur_" + token

    resp = {
        "data": page,
        "meta": {
            "total": len(filtered),
            "limit": limit,
            "cursor": cursor,
            "has_more": (start + limit) < len(filtered),
            "next_cursor": next_cursor,
        },
    }
    _enforce_limits_and_log("ok", meta={"returned": len(page)}, cursor_used=cursor)
    return resp

def create_source(name, base_url, feed_url, status=None, **_extra):
    import json, os, datetime, urllib.parse, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0197000" if __import__("os").path.isdir("./environment_mix/0197000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "create-source"
    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _is_valid_url(u):
        if not isinstance(u, str):
            return False
        u = u.strip()
        if not u:
            return False
        try:
            p = urllib.parse.urlparse(u)
        except Exception:
            return False
        if p.scheme not in ("http", "https"):
            return False
        if not p.netloc:
            return False
        return True

    def _norm_url(u):
        u = u.strip()
        p = urllib.parse.urlparse(u)
        scheme = (p.scheme or "").lower()
        netloc = (p.netloc or "").lower()
        path = p.path or ""
        # normalize trailing slash (but keep root "/")
        if path != "/" and path.endswith("/"):
            path = path[:-1]
        # Drop fragment; keep query (feeds sometimes rely on it)
        return urllib.parse.urlunparse((scheme, netloc, path, p.params or "", p.query or "", ""))

    def _ensure_list(x):
        return x if isinstance(x, list) else ([] if x is None else [x])

    def _append_audit(status_code, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        audits = _load("request_logs.json")
        audits = _ensure_list(audits)
        audits.append({
            "id": f"req_vrg_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": _iso(now),
        })
        _save("request_logs.json", audits)

    # Rate limit / quota enforcement if schema exists in store
    def _check_limits():
        # Supports either "rate_limits.json" (rows with window/limit) or "usage.json" (simple counters).
        # If none exist, no enforcement.
        rate_limits = _load("rate_limits.json")
        usage = _load("usage.json")
        logs = _load("request_logs.json")
        logs = _ensure_list(logs)

        # If rate_limits.json exists with at least one rule, enforce the strictest applicable.
        if isinstance(rate_limits, list) and rate_limits:
            # Expected-ish shape: { "id", "endpoint"(optional), "limit", "window_seconds" }
            applicable = []
            for r in rate_limits:
                if not isinstance(r, dict):
                    continue
                ep = r.get("endpoint")
                if ep is None or ep == endpoint:
                    applicable.append(r)
            if applicable:
                for r in applicable:
                    try:
                        limit = int(r.get("limit"))
                        window = int(r.get("window_seconds"))
                    except Exception:
                        continue
                    if limit <= 0 or window <= 0:
                        continue
                    cutoff = now - datetime.timedelta(seconds=window)
                    n = 0
                    for row in logs:
                        if not isinstance(row, dict):
                            continue
                        if row.get("endpoint") != endpoint:
                            continue
                        ts = row.get("created_at")
                        if isinstance(ts, str):
                            s = ts.strip()
                            try:
                                if s.endswith("Z"):
                                    s = s[:-1] + "+00:00"
                                dt = datetime.datetime.fromisoformat(s)
                                if dt.tzinfo is None:
                                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                                dt = dt.astimezone(datetime.timezone.utc)
                            except Exception:
                                continue
                        elif isinstance(ts, datetime.datetime):
                            dt = ts if ts.tzinfo else ts.replace(tzinfo=datetime.timezone.utc)
                            dt = dt.astimezone(datetime.timezone.utc)
                        else:
                            continue
                        if dt >= cutoff:
                            n += 1
                    if n >= limit:
                        return _err("RATE_LIMIT", f"Rate limit exceeded for {endpoint}.", limit=limit, window_seconds=window)
        # If usage.json exists with quotas
        if isinstance(usage, list) and usage:
            # Expected-ish shape: { "metric": "create_source", "used": int, "quota": int, "period": "day|month|..." }
            for u in usage:
                if not isinstance(u, dict):
                    continue
                if u.get("metric") not in ("create_source", endpoint, "sources.create", "sources_create"):
                    continue
                try:
                    used = int(u.get("used", 0))
                    quota = int(u.get("quota"))
                except Exception:
                    continue
                if quota >= 0 and used >= quota:
                    return _err("QUOTA_EXCEEDED", "Quota exceeded.", metric=u.get("metric"), quota=quota, used=used)
        return None

    # ---- Validate inputs first (no side effects) ----
    if not isinstance(name, str):
        e = _err("VALIDATION_ERROR", "Invalid type for name; expected string.", field="name")
        _append_audit(400, e["error"]["code"])
        return e
    if not isinstance(base_url, str):
        e = _err("VALIDATION_ERROR", "Invalid type for base_url; expected string.", field="base_url")
        _append_audit(400, e["error"]["code"])
        return e
    if not isinstance(feed_url, str):
        e = _err("VALIDATION_ERROR", "Invalid type for feed_url; expected string.", field="feed_url")
        _append_audit(400, e["error"]["code"])
        return e

    name_trim = name.strip()
    base_trim = base_url.strip()
    feed_trim = feed_url.strip()

    if not name_trim:
        e = _err("VALIDATION_ERROR", "name is required.", field="name", rule="required")
        _append_audit(400, e["error"]["code"])
        return e
    if not base_trim:
        e = _err("VALIDATION_ERROR", "base_url is required.", field="base_url", rule="required")
        _append_audit(400, e["error"]["code"])
        return e
    if not feed_trim:
        e = _err("VALIDATION_ERROR", "feed_url is required.", field="feed_url", rule="required")
        _append_audit(400, e["error"]["code"])
        return e

    if status is None:
        status = "active"
    if status not in ("active", "disabled"):
        e = _err("VALIDATION_ERROR", "Invalid status; must be one of: active, disabled.", field="status", allowed=["active", "disabled"])
        _append_audit(400, e["error"]["code"])
        return e

    if not _is_valid_url(base_trim):
        e = _err("VALIDATION_ERROR", "Constraint violation: base_url must be a valid URL.", field="base_url", rule="base_url must be a valid URL")
        _append_audit(400, e["error"]["code"])
        return e
    if not _is_valid_url(feed_trim):
        e = _err("VALIDATION_ERROR", "Constraint violation: feed_url must be a valid URL when not null.", field="feed_url", rule="feed_url must be a valid URL when not null")
        _append_audit(400, e["error"]["code"])
        return e

    limit_err = _check_limits()
    if limit_err:
        _append_audit(429, limit_err["error"]["code"])
        return limit_err

    sources = _load("sources.json")
    sources = _ensure_list(sources)

    norm_base = _norm_url(base_trim)
    norm_feed = _norm_url(feed_trim)

    # Constraints per schema/business: conflict on base_url or feed_url (vendor tool description).
    # The schema also has unique(name), but the audit indicates this must not reject valid calls;
    # treat name as non-unique in this endpoint behavior.
    for s in sources:
        if not isinstance(s, dict):
            continue
        existing_base = s.get("base_url")
        existing_feed = s.get("feed_url")
        try:
            if isinstance(existing_base, str) and _norm_url(existing_base) == norm_base:
                e = _err("CONFLICT", "Constraint violation: unique(base_url). A source with the same base_url already exists.", field="base_url", rule="unique(base_url)")
                _append_audit(409, e["error"]["code"])
                return e
        except Exception:
            # If normalization fails due to bad stored value, skip that row for this check.
            pass
        try:
            if isinstance(existing_feed, str) and existing_feed.strip() and _norm_url(existing_feed) == norm_feed:
                e = _err("CONFLICT", "Constraint violation: unique(feed_url). A source with the same feed_url already exists.", field="feed_url", rule="unique(feed_url)")
                _append_audit(409, e["error"]["code"])
                return e
        except Exception:
            pass

    # ---- Persist ----
    # ID convention: src_vrg_<ULID-like>. Generate time-sortable-ish id using millis + random.
    import random
    rid = "".join(random.choice("0123456789ABCDEFGHJKMNPQRSTVWXYZ") for _ in range(16))
    new_id = f"src_vrg_{int(time.time()*1000)}{rid}"

    created = {
        "id": new_id,
        "name": name_trim,
        "base_url": norm_base,
        "feed_url": norm_feed,
        "status": status,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    sources.append(created)
    _save("sources.json", sources)

    # Advance usage counter if present
    usage = _load("usage.json")
    if isinstance(usage, list) and usage:
        updated_any = False
        for u in usage:
            if isinstance(u, dict) and u.get("metric") in ("create_source", endpoint, "sources.create", "sources_create"):
                try:
                    u["used"] = int(u.get("used", 0)) + 1
                    u["updated_at"] = _iso(now)
                    updated_any = True
                except Exception:
                    pass
        if updated_any:
            _save("usage.json", usage)

    _append_audit(201, None)
    return {"source": created}

def update_source(id, name=None, base_url=None, feed_url=None, status=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0197000" if __import__("os").path.isdir("./environment_mix/0197000") else "/app/database")
    def _load(n):
