            try:
                s = v.strip()
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _find_log_file():
        for cand in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json", "api_requests.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                return cand
        return None

    log_file = _find_log_file()

    def _read_logs():
        if not log_file:
            return []
        rows = _load(log_file)
        return rows if isinstance(rows, list) else []

    def _write_logs(rows):
        if log_file:
            _save(log_file, rows)

    def _enforce_limits_and_log(final_status, error_code=None, error_message=None, meta=None):
        rows = _read_logs()
        if log_file:
            one_min_ago = now - datetime.timedelta(seconds=60)
            one_day_ago = now - datetime.timedelta(days=1)
            recent_min = 0
            recent_day = 0
            for r in rows:
                if not isinstance(r, dict):
                    continue
                ts = _dt_parse(r.get("timestamp") or r.get("created_at"))
                if not ts:
                    continue
                if ts >= one_min_ago:
                    recent_min += 1
                if ts >= one_day_ago:
                    recent_day += 1
            if recent_min >= 120:
                latency_ms = int((time.time() - t0) * 1000)
                rows.append({
                    "id": f"req_{len(rows)+1}",
                    "endpoint": endpoint,
                    "status": "RATE_LIMIT",
                    "error_code": "RATE_LIMIT",
                    "error_message": "Rate limit exceeded (120 requests/min).",
                    "latency_ms": latency_ms,
                    "timestamp": _dt_iso(now),
                    "meta": meta or {},
                })
                _write_logs(rows)
                return _err("RATE_LIMIT", "Rate limit exceeded (120 requests/min).")
            if recent_day >= 10000:
                latency_ms = int((time.time() - t0) * 1000)
                rows.append({
                    "id": f"req_{len(rows)+1}",
                    "endpoint": endpoint,
                    "status": "QUOTA_EXCEEDED",
                    "error_code": "QUOTA_EXCEEDED",
                    "error_message": "Daily quota exceeded (10000 requests/day).",
                    "latency_ms": latency_ms,
                    "timestamp": _dt_iso(now),
                    "meta": meta or {},
                })
                _write_logs(rows)
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded (10000 requests/day).")

        if log_file:
            latency_ms = int((time.time() - t0) * 1000)
            rows.append({
                "id": f"req_{len(rows)+1}",
                "endpoint": endpoint,
                "status": final_status,
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": latency_ms,
                "timestamp": _dt_iso(now),
                "meta": meta or {},
            })
            _write_logs(rows)
        return None

    if not isinstance(id, str) or not id.strip():
        e = _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")
        _enforce_limits_and_log("error", e["error"]["code"], e["error"]["message"], meta={"field": "id"})
        return e

    # Validate provided fields
    if name is not None and (not isinstance(name, str) or not name.strip()):
        e = _err("VALIDATION_ERROR", "name must be a non-empty string when provided", field="name")
        _enforce_limits_and_log("error", e["error"]["code"], e["error"]["message"], meta={"field": "name"})
        return e
    if base_url is not None and (not isinstance(base_url, str) or not base_url.strip()):
        e = _err("VALIDATION_ERROR", "base_url must be a non-empty string when provided", field="base_url")
        _enforce_limits_and_log("error", e["error"]["code"], e["error"]["message"], meta={"field": "base_url"})
        return e
    if feed_url is not None and (not isinstance(feed_url, str) or not feed_url.strip()):
        e = _err("VALIDATION_ERROR", "feed_url must be a non-empty string when provided", field="feed_url")
        _enforce_limits_and_log("error", e["error"]["code"], e["error"]["message"], meta={"field": "feed_url"})
        return e
    if status is not None and (not isinstance(status, str) or status not in ("active", "disabled")):
        e = _err("VALIDATION_ERROR", "status must be one of: active, disabled", field="status")
        _enforce_limits_and_log("error", e["error"]["code"], e["error"]["message"], meta={"field": "status"})
        return e

    from urllib.parse import urlparse
    def _is_valid_url(u):
        if not isinstance(u, str):
            return False
        u = u.strip()
        if not u:
            return False
        try:
            p = urlparse(u)
        except Exception:
            return False
        return p.scheme in ("http", "https") and bool(p.netloc)

    if base_url is not None and not _is_valid_url(base_url):
        e = _err("VALIDATION_ERROR", "base_url must be a valid URL", field="base_url")
        _enforce_limits_and_log("error", e["error"]["code"], e["error"]["message"], meta={"field": "base_url"})
        return e
    if feed_url is not None and not _is_valid_url(feed_url):
        e = _err("VALIDATION_ERROR", "feed_url must be a valid URL", field="feed_url")
        _enforce_limits_and_log("error", e["error"]["code"], e["error"]["message"], meta={"field": "feed_url"})
        return e

    limit_err = _enforce_limits_and_log("pending", meta={"phase": "precheck"})
    if isinstance(limit_err, dict) and "error" in limit_err:
        return limit_err

    sources = _load("sources.json")
    if not isinstance(sources, list):
        sources = []

    idx = None
    for i, s in enumerate(sources):
        if isinstance(s, dict) and s.get("id") == id:
            idx = i
            break
    if idx is None:
        e = _err("NOT_FOUND", "source not found", id=id)
        _enforce_limits_and_log("error", e["error"]["code"], e["error"]["message"], meta={"id": id})
        return e

    row = sources[idx]
    old_status = row.get("status")

    # Lifecycle transition check only if status changes
    if status is not None and status != old_status:
        allowed = {"active": {"disabled"}, "disabled": {"active"}}
        if old_status not in allowed or status not in allowed.get(old_status, set()):
            e = _err("INVALID_TRANSITION", f"status transition not allowed: {old_status} -> {status}", field="status")
            _enforce_limits_and_log("error", e["error"]["code"], e["error"]["message"], meta={"from": old_status, "to": status})
            return e

    # Uniqueness constraints: unique(name), unique(feed_url) where not null.
    new_name = name.strip() if isinstance(name, str) else row.get("name")
    new_feed = feed_url.strip() if isinstance(feed_url, str) else row.get("feed_url")
    for s in sources:
        if not isinstance(s, dict):
            continue
        if s.get("id") == id:
            continue
        if (s.get("name") or "").strip() == (new_name or "").strip():
            e = _err("CONFLICT", "Update would conflict with an existing name.", field="name")
            _enforce_limits_and_log("error", e["error"]["code"], e["error"]["message"], meta={"field": "name"})
            return e
        if new_feed is not None and s.get("feed_url") is not None and (s.get("feed_url") or "").strip() == (new_feed or "").strip():
            e = _err("CONFLICT", "Update would conflict with an existing feed_url.", field="feed_url")
            _enforce_limits_and_log("error", e["error"]["code"], e["error"]["message"], meta={"field": "feed_url"})
            return e

    # Apply updates
    if name is not None:
        row["name"] = name.strip()
    if base_url is not None:
        row["base_url"] = base_url.strip()
    if feed_url is not None:
        row["feed_url"] = feed_url.strip()
    if status is not None:
        row["status"] = status

    row["updated_at"] = _dt_iso(now)
    sources[idx] = row
    _save("sources.json", sources)

    _enforce_limits_and_log("ok", meta={"id": id})
    return {"data": row}

def create_crawl_run(source_id, run_type, lookback_days=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0197000" if __import__("os").path.isdir("./environment_mix/0197000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _log_and_maybe_limit(status_code, credential_id=None, extra=None, http_status=None):
        extra = extra or {}
        req_file = None
        for cand in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json", "api_requests.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                req_file = cand
                break
        if not req_file:
            return None
        rows = _load(req_file)
        if not isinstance(rows, list):
            rows = []
        cred = credential_id or "ambient"
        one_min_ago = now - datetime.timedelta(seconds=60)
        one_day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(v):
            if isinstance(v, str):
                try:
                    dt = datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=datetime.timezone.utc)
                    return dt.astimezone(datetime.timezone.utc)
                except Exception:
                    return None
            return None

        recent_min = 0
        recent_day = 0
        for r in rows:
            if not isinstance(r, dict) or r.get("credential_id") != cred:
                continue
            ts = _parse_ts(r.get("timestamp") or r.get("created_at"))
            if not ts:
                continue
            if ts >= one_min_ago:
                recent_min += 1
            if ts >= one_day_ago:
                recent_day += 1

        if recent_min >= 120:
            rows.append({
                "id": f"req_{uuid.uuid4().hex}",
                "endpoint": "create-crawl-run",
                "credential_id": cred,
                "status": "RATE_LIMIT",
                "http_status": 429,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now.isoformat().replace("+00:00", "Z"),
                **extra
            })
            _save(req_file, rows)
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if recent_day >= 10000:
            rows.append({
                "id": f"req_{uuid.uuid4().hex}",
                "endpoint": "create-crawl-run",
                "credential_id": cred,
                "status": "QUOTA_EXCEEDED",
                "http_status": 429,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now.isoformat().replace("+00:00", "Z"),
                **extra
            })
            _save(req_file, rows)
            return _err("QUOTA_EXCEEDED", "Quota exceeded.")
        rows.append({
            "id": f"req_{uuid.uuid4().hex}",
            "endpoint": "create-crawl-run",
            "credential_id": cred,
            "status": status_code,
            "http_status": http_status if http_status is not None else (200 if status_code == "OK" else 400),
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now.isoformat().replace("+00:00", "Z"),
            **extra
        })
        _save(req_file, rows)
        return None

    limit_err = _log_and_maybe_limit("PENDING")
    if isinstance(limit_err, dict) and "error" in limit_err:
        return limit_err

    if not isinstance(source_id, str) or not source_id.strip():
        _log_and_maybe_limit("VALIDATION_ERROR", http_status=400)
        return _err("VALIDATION_ERROR", "Field 'source_id' must be a non-empty string.")
    if run_type not in ("scheduled", "manual", "backfill"):
        _log_and_maybe_limit("VALIDATION_ERROR", http_status=400)
        return _err("VALIDATION_ERROR", "Field 'run_type' must be one of: scheduled, manual, backfill.")
    if lookback_days is not None:
        if not isinstance(lookback_days, int):
            _log_and_maybe_limit("VALIDATION_ERROR", http_status=400)
            return _err("VALIDATION_ERROR", "Field 'lookback_days' must be an integer when provided.")
        if lookback_days < 1 or lookback_days > 3650:
            _log_and_maybe_limit("VALIDATION_ERROR", http_status=400)
            return _err("VALIDATION_ERROR", "Constraint violation: lookback_days must be between 1 and 3650.",
                        min=1, max=3650)

    sources = _load("sources.json")
    if not isinstance(sources, list):
        sources = []
    src = None
    for s in sources:
        if isinstance(s, dict) and s.get("id") == source_id:
            src = s
            break
    if not src:
        _log_and_maybe_limit("NOT_FOUND", http_status=404)
        return _err("NOT_FOUND", "Source not found.", source_id=source_id)

    if run_type == "scheduled" and src.get("status") == "disabled":
        _log_and_maybe_limit("VALIDATION_ERROR", http_status=400)
        return _err("VALIDATION_ERROR", "Cannot create scheduled crawl runs for disabled sources.",
                    source_id=source_id)

    runs = _load("crawl_runs.json")
    if not isinstance(runs, list):
        runs = []

    # Duplicate run detection: prevent enqueuing multiple queued/running runs for same source+type+lookback_days
    for r in runs:
        if not isinstance(r, dict):
            continue
        if r.get("source_id") == source_id and r.get("run_type") == run_type and r.get("status") in ("queued", "running"):
            if (r.get("lookback_days") is None and lookback_days is None) or (r.get("lookback_days") == lookback_days):
                _log_and_maybe_limit("CONFLICT", http_status=409)
                return _err("CONFLICT", "A crawl run is already queued or running for this source with the same parameters.",
                            source_id=source_id, run_type=run_type, lookback_days=lookback_days)

    new_id = f"cr_{uuid.uuid4().hex}"
    row = {
        "id": new_id,
        "source_id": source_id,
        "run_type": run_type,
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "lookback_days": lookback_days,
        "fetched_count": 0,
        "upserted_count": 0,
        "error_message": None,
        "created_at": now.isoformat().replace("+00:00", "Z"),
        "updated_at": now.isoformat().replace("+00:00", "Z"),
    }
    runs.append(row)
    _save("crawl_runs.json", runs)

    _log_and_maybe_limit("OK", extra={"resource_id": new_id})
    return {"crawl_run": row}

def update_crawl_run(id, status=None, started_at=None, finished_at=None, fetched_count=None, upserted_count=None, error_message=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0197000" if __import__("os").path.isdir("./environment_mix/0197000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    endpoint = "update-crawl-run"

    def _dt_parse(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _dt_iso(dt):
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _find_log_file():
        for cand in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json", "api_requests.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                return cand
        return None

    log_file = _find_log_file()

    def _read_logs():
        if not log_file:
            return []
        rows = _load(log_file)
        return rows if isinstance(rows, list) else []

    def _write_logs(rows):
        if log_file:
            _save(log_file, rows)

    def _log_and_maybe_limit(final_status, error=None, meta=None):
        rows = _read_logs()
        if log_file:
            one_min_ago = now - datetime.timedelta(seconds=60)
            one_day_ago = now - datetime.timedelta(days=1)
            recent_min = 0
            recent_day = 0
            for r in rows:
                if not isinstance(r, dict):
                    continue
                ts = _dt_parse(r.get("timestamp") or r.get("created_at") or r.get("time"))
                if not ts:
                    continue
                if ts >= one_min_ago:
                    recent_min += 1
                if ts >= one_day_ago:
                    recent_day += 1
            if recent_min >= 120:
                latency_ms = int((time.time() - t0) * 1000)
                rows.append({
                    "id": "req_" + hashlib.sha256(f"{endpoint}:{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
                    "endpoint": endpoint,
                    "status": "error",
                    "error_code": "RATE_LIMIT",
                    "error_message": "Rate limit exceeded.",
                    "timestamp": _dt_iso(now),
                    "latency_ms": latency_ms,
                    "meta": meta or {}
                })
                _write_logs(rows)
                return _err("RATE_LIMIT", "Rate limit exceeded.")
            if recent_day >= 5000:
                latency_ms = int((time.time() - t0) * 1000)
                rows.append({
                    "id": "req_" + hashlib.sha256(f"{endpoint}:{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
                    "endpoint": endpoint,
                    "status": "error",
                    "error_code": "QUOTA_EXCEEDED",
                    "error_message": "Daily quota exceeded.",
                    "timestamp": _dt_iso(now),
                    "latency_ms": latency_ms,
                    "meta": meta or {}
                })
                _write_logs(rows)
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        if log_file:
            latency_ms = int((time.time() - t0) * 1000)
            row = {
                "id": "req_" + hashlib.sha256(f"{endpoint}:{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
                "endpoint": endpoint,
                "status": final_status,
                "timestamp": _dt_iso(now),
                "latency_ms": latency_ms,
                "meta": meta or {}
            }
            if error:
                row["error_code"] = error.get("code")
                row["error_message"] = error.get("message")
            rows.append(row)
            _write_logs(rows)
        return None

    # validate id
    if not isinstance(id, str) or not id.strip():
        e = _err("VALIDATION_ERROR", "id is required and must be a non-empty string", field="id")
        maybe = _log_and_maybe_limit("error", error=e["error"], meta={"id": id})
        return maybe if maybe else e
    idv = id.strip()

    # Load crawl runs
    runs = _load("crawl_runs.json")
    if not isinstance(runs, list):
        runs = []

    # Realistic behaviour: some clients accidentally send source_id in id field (audit shows src_* passed).
    # If the given id does not match a crawl run, but matches a source id, update the most recent crawl run for that source.
    target_idx = None
    for i, r in enumerate(runs):
        if isinstance(r, dict) and r.get("id") == idv:
            target_idx = i
            break

    if target_idx is None:
        # try resolve as source_id
        sources = _load("sources.json")
        if not isinstance(sources, list):
            sources = []
        source_exists = any(isinstance(s, dict) and s.get("id") == idv for s in sources)
        if source_exists:
            candidates = []
            for i, r in enumerate(runs):
                if not isinstance(r, dict):
                    continue
                if r.get("source_id") != idv:
                    continue
                created = _dt_parse(r.get("created_at")) or _dt_parse(r.get("updated_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
                candidates.append((created, i))
            if candidates:
                candidates.sort(key=lambda x: x[0], reverse=True)
                target_idx = candidates[0][1]
        if target_idx is None:
            e = _err("NOT_FOUND", "crawl run not found", id=idv)
            maybe = _log_and_maybe_limit("error", error=e["error"], meta={"id": idv})
            return maybe if maybe else e

    run = runs[target_idx]
    if not isinstance(run, dict):
        e = _err("NOT_FOUND", "crawl run not found", id=idv)
        maybe = _log_and_maybe_limit("error", error=e["error"], meta={"id": idv})
        return maybe if maybe else e

    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    if status is not None and status not in allowed_status:
        e = _err("VALIDATION_ERROR", "status must be one of: queued, running, succeeded, failed, cancelled", field="status")
        maybe = _log_and_maybe_limit("error", error=e["error"], meta={"id": idv, "status": status})
        return maybe if maybe else e

    # parse timestamps if provided
    started_dt = _dt_parse(started_at) if started_at is not None else None
    finished_dt = _dt_parse(finished_at) if finished_at is not None else None
    if started_at is not None and started_dt is None:
        e = _err("VALIDATION_ERROR", "started_at must be an RFC3339 timestamp", field="started_at")
        maybe = _log_and_maybe_limit("error", error=e["error"], meta={"id": idv})
        return maybe if maybe else e
    if finished_at is not None and finished_dt is None:
        e = _err("VALIDATION_ERROR", "finished_at must be an RFC3339 timestamp", field="finished_at")
        maybe = _log_and_maybe_limit("error", error=e["error"], meta={"id": idv})
        return maybe if maybe else e

    def _is_nonneg_int(x):
        return isinstance(x, int) and not isinstance(x, bool) and x >= 0

    if fetched_count is not None and not _is_nonneg_int(fetched_count):
        e = _err("VALIDATION_ERROR", "fetched_count must be a non-negative integer", field="fetched_count")
        maybe = _log_and_maybe_limit("error", error=e["error"], meta={"id": idv})
        return maybe if maybe else e
    if upserted_count is not None and not _is_nonneg_int(upserted_count):
        e = _err("VALIDATION_ERROR", "upserted_count must be a non-negative integer", field="upserted_count")
        maybe = _log_and_maybe_limit("error", error=e["error"], meta={"id": idv})
        return maybe if maybe else e
    if error_message is not None and (not isinstance(error_message, str) or not error_message.strip()):
        e = _err("VALIDATION_ERROR", "error_message must be a non-empty string when provided", field="error_message")
        maybe = _log_and_maybe_limit("error", error=e["error"], meta={"id": idv})
        return maybe if maybe else e

    # lifecycle transitions
    current_status = run.get("status")
    transitions = {
        "queued": {"running", "cancelled"},
        "running": {"succeeded", "failed", "cancelled"},
        "succeeded": set(),
        "failed": set(),
        "cancelled": set(),
    }
    if current_status not in transitions:
        # treat as validation issue with stored row
        e = _err("VALIDATION_ERROR", "crawl run has invalid stored status", stored_status=current_status)
        maybe = _log_and_maybe_limit("error", error=e["error"], meta={"id": idv})
        return maybe if maybe else e

    # apply updates with rules
    new_status = current_status
    if status is not None:
        if status != current_status:
            if status not in transitions[current_status]:
                e = _err("INVALID_TRANSITION", f"status transition not allowed: {current_status} -> {status}", from_status=current_status, to_status=status)
                maybe = _log_and_maybe_limit("error", error=e["error"], meta={"id": idv})
                return maybe if maybe else e
            new_status = status

    # When transitioning to running/succeeded/failed/cancelled, started_at must be not null unless already set
    if new_status in ("running", "succeeded", "failed", "cancelled"):
        if started_dt is None:
            existing_started = _dt_parse(run.get("started_at")) if run.get("started_at") is not None else None
            if existing_started is None and new_status != "queued":
                # allow server to set started_at if missing (realistic)
                started_dt = now

    # finished_at rules
    if new_status in ("succeeded", "failed", "cancelled"):
        if finished_dt is None:
            existing_finished = _dt_parse(run.get("finished_at")) if run.get("finished_at") is not None else None
            if existing_finished is None:
                e = _err("VALIDATION_ERROR", "finished_at is required when status is succeeded, failed, or cancelled", field="finished_at")
                maybe = _log_and_maybe_limit("error", error=e["error"], meta={"id": idv, "status": new_status})
                return maybe if maybe else e

    # failed requires error_message and finished_at
    if new_status == "failed":
        em = (error_message.strip() if isinstance(error_message, str) else None) or (run.get("error_message").strip() if isinstance(run.get("error_message"), str) and run.get("error_message").strip() else None)
        if not em:
            e = _err("VALIDATION_ERROR", "error_message is required when status='failed'", field="error_message", rule="error_message is not null when status='failed'")
            maybe = _log_and_maybe_limit("error", error=e["error"], meta={"id": idv, "status": new_status})
            return maybe if maybe else e
        run["error_message"] = em

    # succeeded requires non-negative counts; allow partial updates if already present
    if new_status == "succeeded":
        fc = fetched_count if fetched_count is not None else run.get("fetched_count")
        uc = upserted_count if upserted_count is not None else run.get("upserted_count")
        if not _is_nonneg_int(fc) or not _is_nonneg_int(uc):
            e = _err("VALIDATION_ERROR", "fetched_count and upserted_count are required as non-negative integers when status='succeeded'", fields=["fetched_count", "upserted_count"])
            maybe = _log_and_maybe_limit("error", error=e["error"], meta={"id": idv, "status": new_status})
            return maybe if maybe else e
        run["fetched_count"] = int(fc)
        run["upserted_count"] = int(uc)

    # apply other fields (when provided)
    if started_dt is not None:
        run["started_at"] = _dt_iso(started_dt)
    if finished_dt is not None:
        run["finished_at"] = _dt_iso(finished_dt)
    if fetched_count is not None:
        run["fetched_count"] = int(fetched_count)
    if upserted_count is not None:
        run["upserted_count"] = int(upserted_count)
    if error_message is not None and new_status != "failed":
        # allow setting error_message only if failed; otherwise validation
        e = _err("VALIDATION_ERROR", "error_message may only be set when status='failed'", field="error_message")
        maybe = _log_and_maybe_limit("error", error=e["error"], meta={"id": idv, "status": new_status})
        return maybe if maybe else e

    # started_at/finished_at ordering constraint
    st = _dt_parse(run.get("started_at"))
    fn = _dt_parse(run.get("finished_at"))
    if st and fn and fn < st:
        e = _err("VALIDATION_ERROR", "finished_at must be >= started_at", rule="finished_at >= started_at when both not null")
        maybe = _log_and_maybe_limit("error", error=e["error"], meta={"id": idv})
        return maybe if maybe else e

    # enforce started_at null unless status in running/succeeded/failed/cancelled
    if new_status == "queued":
        # allow leaving started_at null; if provided, reject
        if run.get("started_at") not in (None, ""):
            e = _err("VALIDATION_ERROR", "started_at must be null when status='queued'", rule="started_at is null unless status in ('running','succeeded','failed','cancelled')")
            maybe = _log_and_maybe_limit("error", error=e["error"], meta={"id": idv})
            return maybe if maybe else e
        if run.get("finished_at") not in (None, ""):
            e = _err("VALIDATION_ERROR", "finished_at must be null when status='queued'", rule="finished_at is null unless status in ('succeeded','failed','cancelled')")
            maybe = _log_and_maybe_limit("error", error=e["error"], meta={"id": idv})
            return maybe if maybe else e

    # commit status + timestamps
    run["status"] = new_status
    run["updated_at"] = _dt_iso(now)
    runs[target_idx] = run
    _save("crawl_runs.json", runs)

    maybe = _log_and_maybe_limit("success", meta={"id": run.get("id"), "resolved_from": idv if run.get("id") == idv else "source_id"})
    if maybe:
        return maybe

    return {"data": run}
